// Data Explorer -- genuinely queries the real research.db SQLite file in the browser
// via sql.js (WebAssembly SQLite). No server, no backend: the .db file is fetched as a
// static binary asset and opened client-side. Read-only by construction (see
// runQuery()'s SELECT-only guard). research.db is generated by build_research_db.py
// directly from the frozen source CSVs -- see the db_metadata / data_sources tables
// (queryable below) for full provenance.

let SQL = null;
let DB = null;

const PRESETS = [
  {
    label: "Data sources (provenance)",
    sql: "SELECT phase, description, source_files, row_count FROM data_sources ORDER BY rowid;"
  },
  {
    label: "V3 baseline: PDR by protocol × node count",
    sql: `SELECT e.routing, e.nodes, COUNT(*) AS seeds, ROUND(AVG(pm.pdr),2) AS pdr_mean_pct
          FROM experiments e JOIN performance_metrics pm ON e.experiment_id = pm.experiment_id
          WHERE e.phase = 'v3_baseline'
          GROUP BY e.routing, e.nodes ORDER BY e.routing, e.nodes;`
  },
  {
    label: "Bottleneck evidence: gateway airtime by N (high traffic)",
    sql: `SELECT e.routing, e.nodes, COUNT(*) AS seeds,
                 ROUND(AVG(bm.gateway_airtime_frac),4) AS gw_airtime_mean,
                 ROUND(AVG(bm.mac_queue_drops),1) AS mac_queue_drops_mean
          FROM experiments e JOIN bottleneck_metrics bm ON e.experiment_id = bm.experiment_id
          WHERE e.phase = 'bottleneck' AND e.traffic = 'high'
          GROUP BY e.routing, e.nodes ORDER BY e.routing, e.nodes;`
  },
  {
    label: "Offered-rate intervention: OLSR PDR vs. rate",
    sql: `SELECT e.nodes, e.offered_rate_kbps AS rate_kbps, COUNT(*) AS seeds,
                 ROUND(AVG(pm.pdr),2) AS pdr_mean_pct
          FROM experiments e JOIN performance_metrics pm ON e.experiment_id = pm.experiment_id
          WHERE e.phase = 'rate_sweep' AND e.routing = 'olsr'
          GROUP BY e.nodes, e.offered_rate_kbps ORDER BY e.nodes, e.offered_rate_kbps DESC;`
  },
  {
    label: "Static/N=50 diagnostic: residual loss per run",
    sql: `SELECT e.seed, e.offered_rate_kbps AS rate_kbps, ROUND(pm.pdr,2) AS pdr_pct,
                 ir.attributed_loss, ir.residual_loss, ROUND(ir.residual_loss_pct,2) AS residual_pct
          FROM experiments e
          JOIN performance_metrics pm ON e.experiment_id = pm.experiment_id
          JOIN intervention_results ir ON e.experiment_id = ir.experiment_id
          WHERE e.phase = 'rate_sweep' AND e.routing = 'static' AND e.nodes = 50
          ORDER BY e.offered_rate_kbps DESC, e.seed;`
  },
  {
    label: "V4 Tier-1: activation vs. Static baseline hop count",
    sql: `SELECT v.sigmoid_x0_risk, v.sigmoid_x0_load, COUNT(*) AS seeds,
                 ROUND(AVG(v.average_hop_count),3) AS mean_hop_count,
                 ROUND(AVG(pm.pdr),2) AS pdr_mean_pct
          FROM experiments e
          JOIN v4_routing_metrics v ON e.experiment_id = v.experiment_id
          JOIN performance_metrics pm ON e.experiment_id = pm.experiment_id
          WHERE e.phase = 'v4_tier1'
          GROUP BY v.sigmoid_x0_risk, v.sigmoid_x0_load ORDER BY mean_hop_count DESC;`
  },
  {
    label: "V4 sensitivity: k_risk × k_load × weight vs. path changes",
    sql: `SELECT v.sigmoid_k_risk, v.sigmoid_k_load, v.weight_risk, v.weight_load, COUNT(*) AS seeds,
                 ROUND(AVG(v.path_changes),2) AS path_changes_mean,
                 ROUND(AVG(v.max_link_utilization),3) AS mlu_mean,
                 ROUND(AVG(pm.pdr),2) AS pdr_mean_pct
          FROM experiments e
          JOIN v4_routing_metrics v ON e.experiment_id = v.experiment_id
          JOIN performance_metrics pm ON e.experiment_id = pm.experiment_id
          WHERE e.phase = 'v4_sensitivity'
          GROUP BY v.sigmoid_k_risk, v.sigmoid_k_load, v.weight_risk, v.weight_load
          ORDER BY path_changes_mean DESC;`
  },
  {
    label: "Reproducibility: pass/fail summary by dataset",
    sql: `SELECT dataset, status, COUNT(*) AS n FROM reproducibility_checks
          GROUP BY dataset, status ORDER BY dataset, status;`
  }
];

// Named htmlEl (not el) to avoid colliding with charts.js's SVG-aware el() --
// both are top-level `function` declarations sharing one global script scope,
// and a same-named later declaration silently overwrites the earlier one,
// which previously caused every chart to be built with document.createElement
// (HTML namespace) instead of document.createElementNS (SVG namespace).
function htmlEl(tag, attrs, children) {
  const e = document.createElement(tag);
  if (attrs) for (const k in attrs) e.setAttribute(k, attrs[k]);
  (children || []).forEach(c => e.appendChild(c));
  return e;
}

function renderResultTable(container, columns, rows) {
  container.innerHTML = "";
  if (!rows.length) { container.innerHTML = '<p class="panel-sub">Query returned no rows.</p>'; return; }
  const table = htmlEl("table", { class: "data" });
  const thead = htmlEl("thead", {}, [htmlEl("tr", {}, columns.map(c => htmlEl("th", {}, [document.createTextNode(c)])))]);
  const tbody = htmlEl("tbody");
  rows.forEach(row => {
    const tr = htmlEl("tr");
    row.forEach(v => {
      const td = htmlEl("td", typeof v === "number" ? { class: "num" } : {});
      td.textContent = v === null ? "—" : String(v);
      tr.appendChild(td);
    });
    tbody.appendChild(tr);
  });
  table.appendChild(thead); table.appendChild(tbody);
  const wrap = htmlEl("div", { style: "overflow-x:auto" }, [table]);
  container.appendChild(wrap);
}

function isSelectOnly(sql) {
  const trimmed = sql.trim().replace(/;+\s*$/, "");
  if (!/^select\s/i.test(trimmed)) return false;
  if (/\b(insert|update|delete|drop|alter|attach|create|replace|pragma)\b/i.test(trimmed)) return false;
  if (trimmed.includes(";")) return false; // no statement chaining
  return true;
}

function runQuery(sql, resultEl, statusEl) {
  if (!isSelectOnly(sql)) {
    statusEl.textContent = "Only a single read-only SELECT statement is permitted.";
    statusEl.style.color = "var(--bad)";
    resultEl.innerHTML = "";
    return;
  }
  try {
    const res = DB.exec(sql);
    if (!res.length) {
      statusEl.textContent = "Query executed — no result set.";
      statusEl.style.color = "var(--text-faint)";
      resultEl.innerHTML = "";
      return;
    }
    const { columns, values } = res[0];
    renderResultTable(resultEl, columns, values);
    statusEl.textContent = `${values.length} row(s) returned.`;
    statusEl.style.color = "var(--ok)";
  } catch (e) {
    statusEl.textContent = "SQL error: " + e.message;
    statusEl.style.color = "var(--bad)";
    resultEl.innerHTML = "";
  }
}

async function initDataExplorer() {
  const statusEl = document.getElementById("de-status");
  const presetsEl = document.getElementById("de-presets");
  const sqlBox = document.getElementById("de-sql");
  const runBtn = document.getElementById("de-run");
  const resultEl = document.getElementById("de-result");
  if (!statusEl) return; // section not present

  statusEl.textContent = "Loading SQLite engine (sql.js, WebAssembly)…";
  try {
    SQL = await initSqlJs({
      locateFile: file => `https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.10.3/${file}`
    });
    statusEl.textContent = "Loading research.db…";
    const buf = await fetch("data/research.db").then(r => {
      if (!r.ok) throw new Error("HTTP " + r.status);
      return r.arrayBuffer();
    });
    DB = new SQL.Database(new Uint8Array(buf));
    statusEl.textContent = "research.db loaded — live SQLite database, queried directly in your browser.";
    statusEl.style.color = "var(--ok)";
  } catch (e) {
    statusEl.textContent = "Could not load the SQLite database: " + e.message;
    statusEl.style.color = "var(--bad)";
    return;
  }

  PRESETS.forEach((p, i) => {
    const b = document.createElement("button");
    b.className = "pill" + (i === 0 ? " active" : "");
    b.textContent = p.label;
    b.addEventListener("click", () => {
      [...presetsEl.children].forEach(c => c.classList.remove("active"));
      b.classList.add("active");
      sqlBox.value = p.sql;
      runQuery(p.sql, resultEl, document.getElementById("de-run-status"));
    });
    presetsEl.appendChild(b);
  });
  sqlBox.value = PRESETS[0].sql;
  runQuery(PRESETS[0].sql, resultEl, document.getElementById("de-run-status"));

  runBtn.addEventListener("click", () => runQuery(sqlBox.value, resultEl, document.getElementById("de-run-status")));
}
